create extension if not exists "uuid-ossp";
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role text default 'staff', created_at timestamptz default now());
create table public.owners (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id), full_name text not null, dni text, phone text, whatsapp text, email text, address text, city text, notes text, created_at timestamptz default now());
create table public.pets (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id), owner_id uuid not null references public.owners(id) on delete restrict, name text not null, species text not null, breed text, sex text, birth_date date, weight numeric, color text, microchip text, photo_path text, status text default 'Activo', notes text, created_at timestamptz default now());
create table public.medical_records (id uuid primary key default uuid_generate_v4(), pet_id uuid not null references public.pets(id) on delete cascade, visit_date date not null default current_date, reason text not null, anamnesis text, physical_exam text, weight numeric, temperature numeric, diagnosis text, treatment text, medication text, indications text, notes text, veterinarian text, created_at timestamptz default now());
create table public.vaccine_catalog (id uuid primary key default uuid_generate_v4(), user_id uuid references auth.users(id), name text not null, species text, active boolean default true, created_at timestamptz default now());
create table public.vaccinations (id uuid primary key default uuid_generate_v4(), pet_id uuid not null references public.pets(id) on delete cascade, vaccine_id uuid references public.vaccine_catalog(id) on delete set null, vaccine_name text not null, applied_date date not null, next_dose_date date, dose_number text, lot text, manufacturer text, veterinarian text, notes text, created_at timestamptz default now());
create table public.reminders (id uuid primary key default uuid_generate_v4(), vaccination_id uuid not null references public.vaccinations(id) on delete cascade, scheduled_for date not null, status text default 'Pendiente', message text, created_at timestamptz default now());
create table public.whatsapp_logs (id uuid primary key default uuid_generate_v4(), reminder_id uuid references public.reminders(id) on delete set null, pet_id uuid references public.pets(id), owner_id uuid references public.owners(id), vaccination_id uuid references public.vaccinations(id), message text not null, method text not null default 'DEMO', status text not null default 'Pendiente', error text, sent_at timestamptz, created_at timestamptz default now());
create index pets_owner_idx on public.pets(owner_id); create index pets_search_idx on public.pets(name, microchip); create index vaccination_next_idx on public.vaccinations(next_dose_date); create index records_pet_idx on public.medical_records(pet_id, visit_date desc);
alter table public.profiles enable row level security; alter table public.owners enable row level security; alter table public.pets enable row level security; alter table public.medical_records enable row level security; alter table public.vaccine_catalog enable row level security; alter table public.vaccinations enable row level security; alter table public.reminders enable row level security; alter table public.whatsapp_logs enable row level security;
create policy "staff only" on public.profiles for all to authenticated using (true) with check (true); create policy "staff only" on public.owners for all to authenticated using (true) with check (true); create policy "staff only" on public.pets for all to authenticated using (true) with check (true); create policy "staff only" on public.medical_records for all to authenticated using (true) with check (true); create policy "staff only" on public.vaccine_catalog for all to authenticated using (true) with check (true); create policy "staff only" on public.vaccinations for all to authenticated using (true) with check (true); create policy "staff only" on public.reminders for all to authenticated using (true) with check (true); create policy "staff only" on public.whatsapp_logs for all to authenticated using (true) with check (true);
